#include "json_store.hpp"
#include <Windows.h>
#include <bcrypt.h>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <stdexcept>
namespace mousebox::application::storage {
std::string utf8(const std::wstring& value){if(value.empty())return {};const auto n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,value.data(),static_cast<int>(value.size()),nullptr,0,nullptr,nullptr);if(!n)throw std::runtime_error("Invalid UTF-16");std::string result(static_cast<std::size_t>(n),'\0');WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,value.data(),static_cast<int>(value.size()),result.data(),n,nullptr,nullptr);return result;}
std::wstring wide(const std::string& value){if(value.empty())return {};const auto n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,value.data(),static_cast<int>(value.size()),nullptr,0);if(!n)throw std::runtime_error("Invalid UTF-8");std::wstring result(static_cast<std::size_t>(n),L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,value.data(),static_cast<int>(value.size()),result.data(),n);return result;}
std::string readBytes(const std::filesystem::path& path,std::uintmax_t maximum){const auto size=std::filesystem::file_size(path);if(size>maximum)throw std::runtime_error("文件不可读或过大");std::ifstream stream(path,std::ios::binary);if(!stream)throw std::runtime_error("无法读取文件");std::string bytes(static_cast<std::size_t>(size),'\0');if(!stream.read(bytes.data(),static_cast<std::streamsize>(bytes.size())))throw std::runtime_error("文件读取不完整");return bytes;}
Json load(const std::filesystem::path& path,std::uintmax_t maximum){auto value=Json::parse(readBytes(path,maximum));if(!value.is_object())throw std::runtime_error("JSON必须为对象");return value;}
bool save(const std::filesystem::path& path,const Json& object){if(!object.is_object())return false;const auto bytes=object.dump();std::error_code ec;if(!path.parent_path().empty())std::filesystem::create_directories(path.parent_path(),ec);if(ec)return false;const auto temp=std::filesystem::path(path.wstring()+L".tmp-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));HANDLE file=CreateFileW(temp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return false;std::size_t offset=0;bool ok=true;while(offset<bytes.size()){DWORD written=0;const auto remaining=static_cast<DWORD>(std::min<std::size_t>(bytes.size()-offset,1024*1024));if(!WriteFile(file,bytes.data()+offset,remaining,&written,nullptr)||!written){ok=false;break;}offset+=written;}if(ok)ok=FlushFileBuffers(file)!=FALSE;CloseHandle(file);if(ok)ok=MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=FALSE;if(!ok)DeleteFileW(temp.c_str());return ok;}
std::string sha256(std::string_view bytes){BCRYPT_ALG_HANDLE algorithm=nullptr;BCRYPT_HASH_HANDLE hash=nullptr;DWORD objectSize=0,digestSize=0,size=0;const auto check=[](NTSTATUS status){if(status<0)throw std::runtime_error("SHA256失败");};check(BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0));try{check(BCryptGetProperty(algorithm,BCRYPT_OBJECT_LENGTH,reinterpret_cast<PUCHAR>(&objectSize),sizeof(objectSize),&size,0));check(BCryptGetProperty(algorithm,BCRYPT_HASH_LENGTH,reinterpret_cast<PUCHAR>(&digestSize),sizeof(digestSize),&size,0));std::vector<unsigned char> object(objectSize),digest(digestSize);check(BCryptCreateHash(algorithm,&hash,object.data(),objectSize,nullptr,0,0));std::size_t offset=0;while(offset<bytes.size()){const auto length=static_cast<ULONG>(std::min<std::size_t>(bytes.size()-offset,1024*1024));check(BCryptHashData(hash,reinterpret_cast<PUCHAR>(const_cast<char*>(bytes.data()+offset)),length,0));offset+=length;}check(BCryptFinishHash(hash,digest.data(),digestSize,0));BCryptDestroyHash(hash);hash=nullptr;BCryptCloseAlgorithmProvider(algorithm,0);algorithm=nullptr;std::ostringstream out;out<<std::hex<<std::setfill('0');for(const auto b:digest)out<<std::setw(2)<<static_cast<unsigned>(b);return out.str();}catch(...){if(hash)BCryptDestroyHash(hash);if(algorithm)BCryptCloseAlgorithmProvider(algorithm,0);throw;}}
}
